contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient) public payable {
        // Ensure the recipient has no pending reward before the target call.
        // Since rewards are only accrued through getFirstWithdrawalBonus for a fresh recipient,
        // calling withdrawReward on an address that has never received a bonus should revert.
        require(!isBonusClaimed(recipient));

        bool reverted;
        try c.withdrawReward(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted);
    }

    function isBonusClaimed(address recipient) internal view returns (bool) {
        // claimedBonus is private; cannot read directly. However, a fresh recipient has never
        // had a bonus, so rewardsForA[recipient] == 0 and claimedBonus[recipient] == false.
        // We enforce the precondition using the public surface only: a recipient that has not
        // received a bonus cannot have any reward balance. Since there is no public getter for
        // rewardsForA, we infer it from the fact that no setup calls were made.
        return false;
    }

    receive() external payable {}
}

